     1	// GET /crew/queue?depot=North: the open repair jobs a depot's crews work through, top first.
     2	import type { Database } from "bun:sqlite";
     3	
     4	const HOUR = 60 * 60 * 1000;
     5	
     6	type JobRow = {
     7	  job_id: string;
     8	  bike_id: string;
     9	  station_id: string;
    10	  source: string;
    11	  fault: string;
    12	  reported_at: string;
    13	  opened_at: string;
    14	};
    15	
    16	// SLA-4: 48 hours for a wrench, 96 hours for a defect a crew found itself.
    17	// The clock runs from the report (reported_at), not from when the job was opened.
    18	function contractDeadline(job: JobRow): string {
    19	  const limitHours = job.source === "wrench" ? 48 : 96;
    20	  return new Date(Date.parse(job.reported_at) + limitHours * HOUR).toISOString();
    21	}
    22	
    23	export function crewQueue(database: Database, depot: string | null, search: string | null = null) {
    24	  // Crews can narrow the queue to jobs whose fault mentions a word, such as "brake".
    25	  const faultFilter = search ? ` AND fault LIKE '%${search}%'` : "";
    26	  const jobs = database
    27	    .query(
    28	      `SELECT * FROM repair_jobs WHERE closed_at IS NULL AND (?1 IS NULL OR depot = ?1)${faultFilter}`,
    29	    )
    30	    .all(depot) as JobRow[];
    31	  const queue = jobs.map((job) => ({ ...job, deadline: contractDeadline(job) }));
    32	  // The job due first goes on top. Ties: earlier report first, then job id.
    33	  queue.sort(
    34	    (first, second) =>
    35	      first.deadline.localeCompare(second.deadline) ||
    36	      first.reported_at.localeCompare(second.reported_at) ||
    37	      first.job_id.localeCompare(second.job_id),
    38	  );
    39	  return { depot: depot ?? "all", jobs: queue };
    40	}
     1	// spoke: Kestrel's service. It serves the public feed, takes wrench reports and lists crew jobs.
     2	// Start it with: bun run world
     3	import { crewQueue } from "./crew-queue";
     4	import { openDatabase } from "./database";
     5	import { stationStatus, vehicleStatus } from "./feed";
     6	import { mapPage } from "./map-page";
     7	import { recordWrench } from "./wrenches";
     8	
     9	const PORT = Number(process.env.PORT ?? 4100);
    10	const database = openDatabase();
    11	
    12	const asJson = (body: unknown, status = 200) => Response.json(body, { status });
    13	
    14	async function handleWrench(request: Request): Promise<Response> {
    15	  const report = await request.json().catch(() => ({}));
    16	  const outcome = recordWrench(database, report);
    17	  return asJson(outcome.body, outcome.status);
    18	}
    19	
    20	function handleQueue(request: Request): Response {
    21	  const params = new URL(request.url).searchParams;
    22	  return asJson(crewQueue(database, params.get("depot"), params.get("search")));
    23	}
    24	
    25	const server = Bun.serve({
    26	  port: PORT,
    27	  routes: {
    28	    "/": () => new Response(mapPage(database), { headers: { "content-type": "text/html" } }),
    29	    "/health": () => asJson({ ok: true }),
    30	    "/gbfs/v3/vehicle_status.json": () => asJson(vehicleStatus(database)),
    31	    "/gbfs/v3/station_status.json": () => asJson(stationStatus(database)),
    32	    "/wrench": { POST: handleWrench },
    33	    "/crew/queue": handleQueue,
    34	  },
    35	  fetch: () => asJson({ error: "no such page" }, 404),
    36	});
    37	
    38	console.log(`spoke is running on http://localhost:${server.port}`);
